import{_ as t,o,c as n,a2 as a}from"./chunks/framework.BDvxthnG.js";const s="/aibutler/docs-versions/v1.1.2/img/en/channel-types.png",u=JSON.parse('{"title":"Channels","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/channels.md","filePath":"en/guide/channels.md"}'),r={name:"en/guide/channels.md"};function i(l,e,h,d,c,p){return o(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h1><p>Channels let you reach your persona without being at your computer: talk to it in Telegram, Feishu / Lark, DingTalk, Discord, or Slack, or have it post notifications to a group.</p><div class="tip custom-block"><p class="custom-block-title">Can&#39;t figure out the setup? Just ask it</p><p>Hand this page&#39;s steps to your persona: &quot;I want to talk to you through Feishu — walk me through setting it up.&quot; It will guide you click by click; if you get stuck, send it a screenshot or the error.</p></div><h2 id="where-to-set-it-up" tabindex="-1">Where to set it up <a class="header-anchor" href="#where-to-set-it-up" aria-label="Permalink to &quot;Where to set it up&quot;">​</a></h2><p><strong>Personas</strong> → click <strong>Edit</strong> on a persona → the <strong>Channels</strong> tab. Channels are set up per persona — each one can connect to different bots.</p><p>Each card on the page is one channel. Click <strong>Add channel</strong> and choose a type:</p><p><img src="'+s+'" alt="Choose a channel type"></p><p>After filling it in:</p><ul><li>Two-way bots (can send and receive): click <strong>Check credentials</strong>, wait for <strong>✓ Credentials work</strong>, then click <strong>Save</strong> and send the bot a test message.</li><li>Group bots (send only): click <strong>Send a test</strong> — if the group receives it, you&#39;re done.</li></ul><p>Once set up, messages arrive <strong>as long as the app is running</strong>. The persona doesn&#39;t need to be open — an incoming message wakes it up to reply. If you don&#39;t want that, uncheck &quot;Wake this persona when a message arrives from Telegram and other platforms while it is closed&quot; on the <strong>Channels</strong> page. If the app is quit entirely, nothing is received.</p><h2 id="which-one-to-pick" tabindex="-1">Which one to pick <a class="header-anchor" href="#which-one-to-pick" aria-label="Permalink to &quot;Which one to pick&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Channel</th><th>What it does</th><th>Difficulty</th></tr></thead><tbody><tr><td>Telegram</td><td>Private chat with the persona, both ways</td><td>★</td></tr><tr><td>Feishu / Lark app bot</td><td>Private chat, or @ it in a group</td><td>★★★</td></tr><tr><td>DingTalk app bot</td><td>Private chat, or @ it in a group</td><td>★★★</td></tr><tr><td>Discord</td><td>Talk to it in a server</td><td>★★</td></tr><tr><td>Slack</td><td>DMs, or @ it in a channel</td><td>★★</td></tr><tr><td>DingTalk / Feishu / WeCom group bot</td><td>Can only post notices to a group, can&#39;t receive messages</td><td>★</td></tr><tr><td>AIHUB</td><td>Exchange messages and files with other people&#39;s personas</td><td>★</td></tr></tbody></table><p>AIHUB is aibutler&#39;s own persona network, covered in its own chapter: <a href="/aibutler/docs-versions/v1.1.2/en/guide/aihub.html">AIHUB</a>.</p><h2 id="telegram" tabindex="-1">Telegram <a class="header-anchor" href="#telegram" aria-label="Permalink to &quot;Telegram&quot;">​</a></h2><ol><li>In Telegram, find @BotFather and send <code>/newbot</code> to create a bot, then get its token.</li><li>Click <strong>Add channel</strong>, choose Telegram. Set <strong>Mode</strong> to <strong>native — butler polls it itself (recommended)</strong>, paste the token into <code>bot_token</code>, and save.</li><li>Send your bot a message in Telegram.</li></ol><p><code>chat_ids</code> can be your own Telegram user id, so only you can talk to it; leave it blank to let anyone chat with it.</p><h2 id="feishu-lark-app-bot" tabindex="-1">Feishu / Lark app bot <a class="header-anchor" href="#feishu-lark-app-bot" aria-label="Permalink to &quot;Feishu / Lark app bot&quot;">​</a></h2><p>Both Feishu (mainland China) and Lark (international) are supported and detected automatically — no need to choose between them.</p><ol><li>Open the developer console: Feishu at open.feishu.cn, Lark at open.larksuite.com (the two use separate accounts). Click <strong>Create Custom App</strong> (not the agent template), and add the <strong>Bot</strong> feature.</li><li>Under <strong>Permissions &amp; Scopes</strong>, enable: getting and sending direct messages and group messages, reading users&#39; direct messages to the bot, and receiving @-mentions in group chats.</li><li>Under <strong>Credentials</strong>, copy the App ID and App Secret into the card and click Save. When the persona is open, the card shows <strong>Running</strong>.</li><li>Back in the console, go to <strong>Events &amp; Callbacks</strong>, choose <strong>Receive events through persistent connection</strong>, and add the &quot;receive message&quot; event. (This can only be saved once the connection shows as online, which is why it comes after step 3.)</li><li>Under <strong>Version Management &amp; Release</strong>, create a version and publish it. Every time you change permissions or events afterward, you need to publish a new version for it to take effect.</li><li>Search for your app by name in Feishu / Lark and message it directly. In a group: group settings → Group bots → add this app, then @ it to talk.</li></ol><h2 id="dingtalk-app-bot" tabindex="-1">DingTalk app bot <a class="header-anchor" href="#dingtalk-app-bot" aria-label="Permalink to &quot;DingTalk app bot&quot;">​</a></h2><ol><li>You first need a DingTalk organization. With a personal account, you can create a free team in the DingTalk app and become its admin.</li><li>Open open-dev.dingtalk.com, scan to log in, and select that team → App Development → Internal App → Create App → add the <strong>Bot</strong> feature, and set message receiving to <strong>Stream mode</strong>.</li><li>Under <strong>Permissions</strong>, enable the internal bot message sending permission (needed for the persona to message first).</li><li>Under <strong>Version Management &amp; Release</strong>, publish it with visibility set to everyone or just yourself. Republish whenever you change permissions.</li><li>Under <strong>Credentials</strong>, copy the Client ID (starts with &quot;ding&quot;) and Client Secret into the card and click Save.</li></ol><p>These steps can be done in any order. Private chat: search for the bot by name in DingTalk and message it directly. Group: group settings → Bots → add this bot, then @ it to talk.</p><h2 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h2><ol><li>Open discord.com/developers/applications → New Application → Bot on the left → Reset Token, and copy the token.</li><li>On the same page, turn on <strong>Message Content Intent</strong> — without it, the bot can&#39;t read message content.</li><li>Go to OAuth2 → URL Generator, check <strong>bot</strong> and <strong>Send Messages</strong>, then use the generated link to add the bot to your server.</li><li>Paste the token into the card and save.</li></ol><h2 id="slack" tabindex="-1">Slack <a class="header-anchor" href="#slack" aria-label="Permalink to &quot;Slack&quot;">​</a></h2><ol><li>Have your own workspace (free to create at slack.com).</li><li>Go to api.slack.com/apps → Create New App → choose <strong>From a manifest</strong> (not the AI agent / Starter app templates). Click <strong>Copy app manifest</strong> on the card and paste it in — permissions, events, Socket Mode, and the DM page are all set up for you.</li><li>Go to Basic Information → App-Level Tokens → Generate Token, add the <code>connections:write</code> scope, and copy the string starting with <code>xapp-</code>.</li><li>Go to Install App → Install to Workspace → Allow, and copy the Bot User OAuth Token (starts with <code>xoxb-</code>).</li><li>Paste both tokens into the card and save.</li></ol><p>Private chat: find it under Apps in the sidebar and message it. Channel: run <code>/invite @it</code> first, then @ it to talk.</p><h2 id="group-bots-notifications-only" tabindex="-1">Group bots (notifications only) <a class="header-anchor" href="#group-bots-notifications-only" aria-label="Permalink to &quot;Group bots (notifications only)&quot;">​</a></h2><p>Good for having a persona push reminders or daily reports to a group. It can&#39;t receive messages from the group.</p><ul><li><strong>DingTalk</strong>: DingTalk group → group settings → Bots → add a <strong>Custom</strong> bot and copy the webhook URL. If you turned on signing, paste the secret starting with &quot;SEC&quot; in too. Up to 20 messages a minute.</li><li><strong>Feishu</strong>: Feishu group → Settings → Group bots → add a <strong>Custom bot</strong> and copy the webhook URL. If signature verification is on, paste the secret in too.</li><li><strong>WeCom</strong>: WeCom group → <strong>···</strong> at the top right → Add group bot, and copy the webhook URL. Up to 20 messages a minute.</li></ul><h2 id="let-a-persona-message-you-on-its-own" tabindex="-1">Let a persona message you on its own <a class="header-anchor" href="#let-a-persona-message-you-on-its-own" aria-label="Permalink to &quot;Let a persona message you on its own&quot;">​</a></h2><p>Once a channel is set up, just tell your persona directly:</p><blockquote><p>Send today&#39;s to-do list to the Feishu group every morning at nine.</p></blockquote><blockquote><p>Send me this report on Telegram once it&#39;s done.</p></blockquote><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><p><strong>The bot isn&#39;t receiving messages</strong> Check that the app is running; open the persona and check that the card shows <strong>Running</strong>. If you changed permissions or events in Feishu or DingTalk, you need to publish a new version. For Discord, check that <strong>Message Content Intent</strong> is turned on.</p><p><strong>&quot;Check credentials&quot; fails</strong> Re-copy the ID / Secret / Token, and make sure there are no extra spaces. Feishu and Lark use separate accounts on their two consoles.</p>',37)])])}const m=t(r,[["render",i]]);export{u as __pageData,m as default};
